4. Data
nlme::Orthodont contains four ordered measurements per subject. visit indexes equal occasion spacing; age is the actual continuous time.

data("Orthodont", package = "nlme")
orth &lt;- as.data.frame(Orthodont) |&gt;
  arrange(Subject, age) |&gt;
  group_by(Subject) |&gt;
  mutate(visit = row_number(), age_c = age - 8, age_f = factor(age)) |&gt;
  ungroup() |&gt;
  mutate(Subject = factor(Subject))

4. Data
Orthodont supplies a Gaussian LMM example and MASS::epil supplies a repeated-count GLMM example.

data("Orthodont", package = "nlme")
orth &lt;- as.data.frame(Orthodont) |&gt;
  arrange(Subject, age) |&gt;
  mutate(Subject = factor(Subject), age_c = age - 8, visit = ave(age, Subject, FUN = seq_along))

data("epil", package = "MASS")
epil &lt;- MASS::epil |&gt;
  mutate(subject = factor(subject), period_c = period - 1)

4. Data
MASS::epil is converted to a binary repeated outcome for a direct population-average versus subject-specific comparison.

data("epil", package = "MASS")
epil &lt;- MASS::epil |&gt;
  mutate(subject = factor(subject), period_c = period - 1, any_seizure = as.integer(y &gt; 0)) |&gt;
  arrange(subject, period)

5. Fit

if (requireNamespace("geepack", quietly = TRUE)) {
  gee_bin &lt;- geepack::geeglm(
    any_seizure ~ trt * period_c + lbase + lage,
    id = subject, waves = period, data = epil,
    family = binomial, corstr = "exchangeable"
  )
}

glmm_bin &lt;- glmer(
  any_seizure ~ trt * period_c + lbase + lage + (1 | subject),
  epil, family = binomial, nAGQ = 7
)

4. Data
nlme::Orthodont is reshaped to one row per subject and one response column per age, producing a four-dimensional longitudinal response vector.

data("Orthodont", package = "nlme")
orth_wide &lt;- as.data.frame(Orthodont) |&gt;
  mutate(age = paste0("age", age)) |&gt;
  select(Subject, Sex, age, distance) |&gt;
  pivot_wider(names_from = age, values_from = distance) |&gt;
  arrange(Subject)
Y &lt;- as.matrix(orth_wide[paste0("age", c(8, 10, 12, 14))])

7. Diagnostics

orth |&gt;
  count(Subject, name = "n_visit") |&gt;
  summarize(min_visits = min(n_visit), max_visits = max(n_visit))





orth |&gt;
  count(Subject, age) |&gt;
  filter(n != 1L)                         # duplicate or absent subject-time keys





colSums(!is.na(Y))                        # pairwise support differs if data are incomplete

 8 10 12 14 
27 27 27 27 


Confirm subject-time uniqueness, ordering, visit support, and whether scheduled time differs materially from actual time before estimating a covariance by lag.

4. Data
An incomplete version of nlme::Orthodont is generated reproducibly with monotone dropout after age 10 depending on observed age-10 distance and sex; this is MAR by construction.

data("Orthodont", package = "nlme")
orth &lt;- as.data.frame(Orthodont) |&gt;
  arrange(Subject, age) |&gt;
  mutate(Subject = factor(Subject), male = as.integer(Sex == "Male"), age_c = age - 8)

set.seed(767)
drop_info &lt;- orth |&gt;
  filter(age == 10) |&gt;
  transmute(
    Subject,
    p_drop = plogis(-0.8 + 0.35 * (distance - mean(distance)) + 0.35 * male),
    dropout = rbinom(n(), 1, p_drop)
  )

orth_miss &lt;- orth |&gt;
  left_join(drop_info, by = "Subject") |&gt;
  mutate(distance_obs = ifelse(dropout == 1 & age &gt;= 12, NA_real_, distance))
with(orth_miss, table(age, is.na(distance_obs)))


